  491 /// [`open_to_write`] beneath `root` (canonical), or `None` where it cannot
  492 /// be: no `openat2` here, or a root that is the destination file itself.
  493 #[cfg(target_os = "linux")]
  494 fn open_beneath(dst: &Path, root: &Path, make: bool) -> Option<std::io::Result<File>> {
  495     use std::os::unix::io::{FromRawFd as _, OwnedFd};
  496     let Some(name) = dst.file_name() else {
  497         return Some(Err(std::io::Error::other(format!(
  498             "{} names no file",
  499             dst.display()
  500         ))));
  501     };
  502     let parent = match dst.parent() {
  503         Some(parent) if !parent.as_os_str().is_empty() => parent,
  504         _ => Path::new("."),
  505     };
  506     // Written beneath the root already, by its own name: as it is — the
  507     // kernel refuses any `..` or link in it that leads out. Else where its
  508     // directory lies beneath the root, found once for the directory.
  509     let lexical = dst
  510         .strip_prefix(root)
  511         .ok()
  512         .filter(|beneath| !beneath.as_os_str().is_empty())
  513         .map(|beneath| {
  514             use std::os::unix::ffi::OsStrExt as _;
  515             let mut bytes = Vec::with_capacity(beneath.as_os_str().len() + 1);
  516             bytes.extend_from_slice(beneath.as_os_str().as_bytes());
  517             Ok(Ok(bytes))
  518         });
  519     let beneath = match lexical.unwrap_or_else(|| place_beneath(parent, root, name)) {
  520         Ok(Ok(beneath)) => beneath,
  521         // A destination that is one file: its root is the file itself.
  522         Ok(Err(directory)) if directory.join(name) == root => return None,
  523         Ok(Err(_)) => {
  524             return Some(Err(std::io::Error::other(format!(
  525                 "{} leads out of the destination",
  526                 dst.display()
  527             ))))
  528         }
  529         Err(error) => return Some(Err(error)),
  530     };
  531     let Ok(beneath) = std::ffi::CString::new(beneath) else {
  532         return Some(Err(std::io::Error::from(std::io::ErrorKind::InvalidInput)));
  533     };
  534     let held = held_root(root)?;
  535     let mut flags = libc::O_WRONLY | libc::O_NONBLOCK | libc::O_CLOEXEC;
  536     if make {
  537         flags |= libc::O_CREAT | libc::O_EXCL;
  538     }
  539     // SAFETY: `open_how` is plain integers; zero is each field's empty
  540     // value, and the three the call reads are set below.
  541     let mut how: libc::open_how = unsafe { std::mem::zeroed() };
  542     how.flags = flags as u64;
  543     how.mode = if make { 0o666 } else { 0 };
  544     how.resolve = libc::RESOLVE_BENEATH | libc::RESOLVE_NO_MAGICLINKS;
  545     // SAFETY: the held root is open for the call; `beneath` is a
  546     // NUL-terminated path and `how` a properly sized `open_how`, both
  547     // outliving it.
  548     let opened = unsafe {
  549         libc::syscall(
  550             libc::SYS_openat2,
  551             held,
  552             beneath.as_ptr(),
  553             &how as *const libc::open_how,
  554             std::mem::size_of::<libc::open_how>(),
  555         )
  556     };
  557     if opened < 0 {
  558         let error = std::io::Error::last_os_error();
  559         return match error.raw_os_error() {
  560             // No `openat2` here (a kernel before 5.6, or a filter that
  561             // refuses it): by the name, as before.
  562             Some(libc::ENOSYS) | Some(libc::EPERM) => None,
  563             Some(libc::EXDEV) => Some(Err(std::io::Error::other(format!(
  564                 "{} leads out of the destination",
  565                 dst.display()
  566             )))),
  567             _ => Some(Err(error)),
  568         };
  569     }
  570     // SAFETY: `opened` is an open descriptor nothing else owns.
  571     Some(Ok(File::from(unsafe {
  572         OwnedFd::from_raw_fd(opened as i32)
  573     })))
  574 }
