  576 #[cfg(target_os = "linux")]
  577 thread_local! {
  578     /// Where the last directory this thread wrote into lies beneath the last
  579     /// root — or its canonical form, where it does not — and the root held:
  580     /// a copy writes many files of one directory in a row. A place gone
  581     /// stale only names, beneath the root, where the directory really is —
  582     /// the open there is still made beneath the root.
  583     #[allow(clippy::type_complexity)]
  584     static LAST_DIRECTORY: std::cell::RefCell<
  585         Vec<(std::path::PathBuf, std::path::PathBuf, Result<Vec<u8>, std::path::PathBuf>)>,
  586     > = const { std::cell::RefCell::new(Vec::new()) };
  587     static HELD_ROOT: std::cell::RefCell<Option<(std::path::PathBuf, std::os::unix::io::OwnedFd)>> =
  588         const { std::cell::RefCell::new(None) };
  589 }
