  591 /// `name` in `parent`, as the bytes of its path beneath `root` (canonical);
  592 /// or, where `parent` does not lie beneath it, `parent`'s canonical form.
  593 /// The place of `parent` is remembered for the next file of it.
  594 #[cfg(target_os = "linux")]
  595 fn place_beneath(
  596     parent: &Path,
  597     root: &Path,
  598     name: &std::ffi::OsStr,
  599 ) -> std::io::Result<Result<Vec<u8>, std::path::PathBuf>> {
  600     use std::os::unix::ffi::OsStrExt as _;
  601     // The few directories a thread's writes go between, the latest first.
  602     const KEPT: usize = 16;
  603     LAST_DIRECTORY.with(|last| {
  604         let mut last = last.borrow_mut();
  605         let found = last
  606             .iter()
  607             .position(|(of, under, _)| of == parent && under == root);
  608         match found {
  609             Some(0) => {}
  610             Some(at) => {
  611                 let entry = last.remove(at);
  612                 last.insert(0, entry);
  613             }
  614             None => {
  615                 let canonical = std::fs::canonicalize(parent)?;
  616                 let place = match canonical.strip_prefix(root) {
  617                     Ok(beneath) => Ok(beneath.as_os_str().as_bytes().to_vec()),
  618                     Err(_) => Err(canonical),
  619                 };
  620                 last.insert(0, (parent.to_path_buf(), root.to_path_buf(), place));
  621                 last.truncate(KEPT);
  622             }
  623         }
  624         let Some((_, _, place)) = last.first() else {
  625             unreachable!("the place was just remembered");
  626         };
  627         Ok(match place {
  628             Ok(directory) => {
  629                 let mut bytes = Vec::with_capacity(directory.len() + name.len() + 2);
  630                 if !directory.is_empty() {
  631                     bytes.extend_from_slice(directory);
  632                     bytes.push(b'/');
  633                 }
  634                 bytes.extend_from_slice(name.as_bytes());
  635                 Ok(bytes)
  636             }
  637             Err(canonical) => Err(canonical.clone()),
  638         })
  639     })
  640 }
