  642 /// The destination's root held (`O_PATH`) — opened once per thread and
  643 /// root — as the descriptor an open beneath it starts from; `None` when it
  644 /// cannot be held (a root that is one file).
  645 #[cfg(target_os = "linux")]
  646 fn held_root(root: &Path) -> Option<std::os::unix::io::RawFd> {
  647     use std::os::unix::ffi::OsStrExt as _;
  648     use std::os::unix::io::{AsRawFd as _, FromRawFd as _, OwnedFd};
  649     HELD_ROOT.with(|held| {
  650         let mut held = held.borrow_mut();
  651         if let Some((of, fd)) = held.as_ref() {
  652             if of == root {
  653                 return Some(fd.as_raw_fd());
  654             }
  655         }
  656         let name = std::ffi::CString::new(root.as_os_str().as_bytes()).ok()?;
  657         // SAFETY: `name` is a NUL-terminated path that outlives the call.
  658         let fd = unsafe {
  659             libc::open(
  660                 name.as_ptr(),
  661                 libc::O_PATH | libc::O_DIRECTORY | libc::O_CLOEXEC,
  662             )
  663         };
  664         if fd < 0 {
  665             return None;
  666         }
  667         // SAFETY: `fd` is an open descriptor nothing else owns.
  668         let fd = unsafe { OwnedFd::from_raw_fd(fd) };
  669         let raw = fd.as_raw_fd();
  670         *held = Some((root.to_path_buf(), fd));
  671         Some(raw)
  672     })
  673 }
