  215         let relative_path = bounded_tail(&self.relative_path, MAX_FAILURE_PATH_BYTES);
  216         crate::generated::FileFailure {
  217             // cr-ecm36-3: said, when the path was shortened.
  218             path_shortened: self.path_shortened || relative_path != self.relative_path,
  219             relative_path,
  220             reason: bounded_head(&self.reason, MAX_FAILURE_REASON_BYTES),
  221             // A cut name is no identity: bytes past the bound are dropped
  222             // whole, and the text stands alone.
  223             raw_relative_path: self
  224                 .raw_relative_path
  225                 .clone()
  226                 .filter(|raw| raw.len() <= MAX_FAILURE_PATH_BYTES)
  227                 .unwrap_or_default(),
  228             left_in_place: self.left_in_place,
