  247 /// A path set in wire form: sorted, bounded by
  248 /// [`MAX_WIRE_LEFT_IN_PLACE_ENCODED_BYTES`], `(paths, truncated)`.
  249 fn wire_path_set(set: &std::collections::HashSet<String>) -> (Vec<String>, bool) {
  250     let mut paths: Vec<&String> = set.iter().collect();
  251     paths.sort();
  252     let mut out = Vec::new();
  253     let mut remaining = MAX_WIRE_LEFT_IN_PLACE_ENCODED_BYTES;
  254     for path in paths {
  255         let cost = path.len().saturating_add(4);
  256         if cost > remaining {
  257             return (out, true);
  258         }
  259         remaining -= cost;
  260         out.push(path.clone());
  261     }
  262     (out, false)
  263 }
