 106 /// Disagreeing non-empty values are an error, not a silent pick.
 107 fn injected_sha(git: Option<String>, release: Option<String>) -> Result<Option<String>, String> {
 108     match (nonempty_env(git), nonempty_env(release)) {
 109         (Some(git_sha), Some(release_sha)) if git_sha != release_sha => Err(format!(
 110             "BLIT_GIT_SHA ({git_sha:?}) and BLIT_RELEASE_SHA ({release_sha:?}) disagree"
