const EXIT_PARTIAL_FAILURE: i32 = 2;

fn blit(ctx: &TestContext, args: &[&str]) -> Output {
    let mut cmd = Command::new(cli_bin());
    cmd.current_dir(&ctx.workspace)
        .arg("--config-dir")
        .arg(&ctx.config_dir)
        .args(args);
    run_with_timeout(cmd, Duration::from_secs(60))
