  585             .with_context(|| format!("reading the link {}", target.display()))?;
  586         if typed_as_directory(&named) {
  587             return not_a_file();
  588         }
  589         target = match target.parent() {
  590             Some(parent) if named.is_relative() => parent.join(named),
  591             _ => named,
  592         };
  593     }
  594     let Some(name) = target.file_name().map(std::ffi::OsStr::to_os_string) else {
